"""Tests for snake.engine.Game class."""
import pytest
from snake.engine import Game


class TestGameConstructor:
    """Test Game initialization."""

    @pytest.mark.parametrize(
        "width,height,seed,x,y",
        [
            (10, 5, 0, 5, 2),   # center for small board
            (20, 10, 42, 10, 5), # standard size
            (3, 3, 99, 1, 1),    # tiny board
        ],
    )
    def test_snake_start_position(self, width, height, seed, x, y):
        """Snake head starts at center (width//2, height//2)."""
        game = Game(width, height, seed)
        assert game.snake[0] == (x, y)

    @pytest.mark.parametrize(
        "width,height",
        [
            (10, 5),
            (20, 10),
            (3, 3),
            (100, 50),
        ],
    )
    def test_snake_initial_length(self, width, height):
        """Snake starts exactly 3 cells long."""
        game = Game(width, height)
        assert len(game.snake) == 3

    @pytest.mark.parametrize(
        "width,height",
        [
            (10, 5),
            (20, 10),
            (7, 7),
        ],
    )
    def test_snake_extends_left(self, width, height):
        """Snake body extends to the left from head."""
        game = Game(width, height)
        head_x = width // 2
        assert game.snake[0] == (head_x, height // 2)
        assert game.snake[1] == (head_x - 1, height // 2)
        assert game.snake[2] == (head_x - 2, height // 2)

    @pytest.mark.parametrize(
        "width,height",
        [
            (10, 5),
            (20, 10),
            (3, 3),
        ],
    )
    def test_score_starts_at_zero(self, width, height):
        """Score starts at 0."""
        game = Game(width, height)
        assert game.score == 0

    @pytest.mark.parametrize(
        "width,height",
        [
            (10, 5),
            (20, 10),
            (3, 3),
        ],
    )
    def test_over_starts_false(self, width, height):
        """Game over starts as False."""
        game = Game(width, height)
        assert game.over is False

    @pytest.mark.parametrize(
        "width,height",
        [
            (10, 5),
            (20, 10),
        ],
    )
    def test_food_is_on_board(self, width, height):
        """Food starts on board at a valid position."""
        game = Game(width, height)
        x, y = game.food
        assert 0 <= x < width
        assert 0 <= y < height

    @pytest.mark.parametrize(
        "width,height",
        [
            (10, 5),
            (20, 10),
        ],
    )
    def test_food_not_on_snake(self, width, height):
        """Food does not spawn on snake initially."""
        game = Game(width, height)
        assert game.food not in game.snake


