class TestGameTurn:
    """Test turn queuing behavior."""

    @pytest.mark.parametrize(
        "initial_direction,queued_turn,expected_queue_len",
        [
            ("right", "up", 1),      # valid new direction
            ("right", "down", 0),     # opposite to current - ignored
            ("right", "left", 0),     # opposite to current - ignored
            ("right", "right", 0),    # equal to current - ignored
        ],
    )
    def test_turn_queues_valid_direction(self, initial_direction, queued_turn, expected_queue_len):
        game = Game(10, 5, seed=42)
        # Set internal state for testing multiple turns on same game instance
        game.turn("right")  # set initial direction to right
        game.turn(queued_turn)
        assert len(game._queue) == expected_queue_len

    @pytest.mark.parametrize(
        "test_cases",
        [
            (["up", "down", "left"], 1),   # up then down cancels, left added
            (["up", "up", "up"], 1),       # only one unique turn queued
            (["right", "up", "left"], 2),  # two turns queued
        ],
    )
    def test_turn_queue_limited_to_two(self, test_cases):
        game = Game(10, 5, seed=42)
        for direction, expected_len in zip(test_cases[0], test_cases[1]):
            game.turn(direction)
            assert len(game._queue) == expected_len

    @pytest.mark.parametrize(
        "width,height",
        [
            (10, 5),
            (20, 10),
            (3, 3),
        ],
    )
    def test_invalid_direction_ignored(self, width, height):
        game = Game(width, height)
        game.turn("invalid")
        assert len(game._queue) == 0

    @pytest.mark.parametrize(
        "width,height",
        [
            (10, 5),
            (20, 10),
        ],
    )
    def test_turn_opposite_to_last_queued_ignored(self, width, height):
        """Opposite direction to last queued turn is ignored."""
        game = Game(width, height)
        game.turn("up")      # queue up
        game.turn("down")    # opposite - should be ignored
        assert len(game._queue) == 1


class TestGameTick:
    """Test tick behavior."""

    @pytest.mark.parametrize(
        "width,height,initial_turns",
        [
            (10, 5, ["right"]),
            (10, 5, ["left"]),
            (10, 5, ["up"]),
            (10, 5, ["down"]),
        ],
    )
    def test_tick_moves_snake(self, width, height, initial_turns):
        game = Game(width, height)
        for direction in initial_turns:
            game.turn(direction)

        before_head = game.snake[0]
        game.tick()

        assert len(game.snake) == 3
        if initial_turns == ["right"]:
            assert game.snake[0][0] == before_head[0] + 1
            assert game.snake[0][1] == before_head[1]
        elif initial_turns == ["left"]:
            assert game.snake[0][0] == before_head[0] - 1
            assert game.snake[0][1] == before_head[1]
        elif initial_turns == ["up"]:
            assert game.snake[0][0] == before_head[0]
            assert game.snake[0][1] == before_head[1] - 1
        elif initial_turns == ["down"]:
            assert game.snake[0][0] == before_head[0]
